-- v26 seed
on conflict (dept,title) do nothing;
) v where not exists(select 1 from public.kpis);

-- registry from current accounts
  select p.full_name,p.hotel,coalesce(p.dept,''),p.created_at::date,p.id,p.active from public.profiles p
  where p.role not in ('pending','admin') and not exists(select 1 from public.employees e where e.profile_id=p.id);
update public.employees e set manager_id=b.id from public.profiles p, public.employees b where p.id=e.profile_id and b.profile_id=p.reports_to and e.manager_id is null;
-- first guess of each person's position from their app role (editable)
update public.employees e set position_id=(select id from public.positions q where q.dept=e.dept and q.title=case
   when e.dept='housekeeping' and p.role='manager' then 'Executive Housekeeper' when e.dept='housekeeping' and p.role='supervisor' then 'Floor Supervisor' when e.dept='housekeeping' then 'House Man'
   when e.dept='hr' and p.role='manager' then 'Human Resources Manager' when e.dept='hr' and p.role='supervisor' then 'Human Resources Supervisor' when e.dept='hr' then 'Human Resources Clerk' end)
 from public.profiles p where p.id=e.profile_id and e.position_id is null;
update public.disc_records r set emp_id=e.id from public.employees e where e.profile_id=r.employee and r.emp_id is null;
